"""Wait before the next delivery attempt."""

CAP_SECONDS = 300


def next_wait(attempt: int) -> int:
    """Exponential backoff in seconds, capped at five minutes."""
    return min(CAP_SECONDS, 2 ** max(attempt, 0))

